<?php
require_once __DIR__.'/includes/functions.php';require_admin();$rows=db()->query("SELECT u.id,u.name,u.email,u.phone,u.created_at,COUNT(a.id) booking_count FROM users u LEFT JOIN appointments a ON a.user_id=u.id WHERE u.role='customer' GROUP BY u.id ORDER BY u.created_at DESC")->fetchAll();$pageTitle='Customers';require __DIR__.'/includes/header.php';
?>
<div class="page-intro"><span class="eyebrow">CUSTOMER DIRECTORY</span><h1>Customers</h1><p>View registered customers and their booking activity.</p></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Appointments</th><th>Joined</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong></td><td><?=e($r['email'])?></td><td><?=e($r['phone'])?></td><td><?=$r['booking_count']?></td><td><?=date('M d, Y',strtotime($r['created_at']))?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty-cell">No customers registered yet.</td></tr><?php endif;?></tbody></table></div><?php require __DIR__.'/includes/footer.php';?>
